# Гайд по району: заголовок по шаблону + секции из данных
def guide(d):
    return dict(
        slug=f"remont-i-pokraska-{d['slug']}",
        h1=f"Покраска и уход за домом {d['loc']}: что учитывать",
        title=f"Покраска и уход за виллой {d['loc']} — советы мастера",
        desc=f"Климат и дома {d['gen']}: что разрушает краску, лак и дерево, когда красить и на что смотреть при выборе мастера.",
        sections=[
            (f"Какие дома {d['loc']}", f"Типичные объекты: {d['houses']}. " + d["intro"]),
            ("Что разрушает покрытия", "Главные риски района: " + "; ".join(d["risks"]) + "."),
            ("Стены и потолки", d["notes"]["walls"]),
            ("Фасад", d["notes"]["facade"]),
            ("Плесень", d["notes"]["mold"]),
            ("Дерево и террасы", d["notes"]["wood"] + " " + d["notes"]["deck"]),
            ("Когда планировать работы", "Наружные работы — в сухой сезон (примерно апрель–октябрь), внутренние можно круглый год, если стены сухие. Плесень лучше обрабатывать сразу после сезона дождей."),
        ])
